-- Resources content for the Notebook sections, Data points and per-source progress (CLAUDE.md, "Resources stay in step with the code").
-- Content only; no schema. Depends on 20261029120000. Rewrites the project-at-a-glance guide for the final tab layout.

select private.rc_release_guide(
  p_slug => 'sourcework-project-overview',
  p_tool_key => 'transcription',
  p_title => 'A project at a glance',
  p_summary => 'See where a project stands, do the next step yourself or with AI, and find any source.',
  p_screen_keys => array['sourcework.project'],
  p_sort_order => 12,
  p_version_note => 'Notebook tab with Sources, Data points and Excerpts; Review on its own tab; progress on each source',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A project opens on where it stands and what to do next. You can do every step yourself, ask AI to do any step, or hand it the rest."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The steps and the next step"}]},{"type":"paragraph","content":[{"type":"text","text":"The row of steps runs Sources, Analyze, Review, Synthesis, Piece. A finished step is a link back to its tab. Under it, one panel names the next step and gives you one button for it: "},{"type":"text","text":"Analyze","marks":[{"type":"bold"}]},{"type":"text","text":" when sources are ready, "},{"type":"text","text":"Review","marks":[{"type":"bold"}]},{"type":"text","text":" when findings and clips are waiting, then Open Synthesis and Start a piece. The steps only report and suggest. You can use any tab at any time."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Tabs"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Notebook","marks":[{"type":"bold"}]},{"type":"text","text":" holds what you browse. Sources lists the project's sources, Data points lists the findings you have accepted or rejected, and Excerpts lists the excerpts made from them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Review","marks":[{"type":"bold"}]},{"type":"text","text":" is where you decide on the findings and clips that Analyze suggested. The number beside it is how many are waiting."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Synthesis, Pieces and Setup work as before."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Run the remaining steps with AI"}]},{"type":"paragraph","content":[{"type":"text","text":"The link under the button opens a dialog that runs the steps still to do, one after another, and hands control back where you choose: after Analyze, after Synthesis, after Outline, or after a first draft. It starts on Analyze, so the Review tab stays yours. Going past Analyze accepts every suggested finding and clip without your review, and the dialog says so before you start; they can be put back for review afterwards. Keep the page open while it runs. Stop after this step ends the run, and what finished is kept."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Find a source"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each source has a bar showing how far it has come: processed, analyzed, reviewed. The word under it says which step it is on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Filter sources searches titles. Show narrows the list to sources not yet analyzed or that need attention, and Sort puts the newest first or sorts by title. The list shows 25 at a time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select a row to open the source. A source that failed to process says why under its title. The ⋮ menu at the end of the row opens the source or removes it from this project."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"+ Add source and the ⋮ menu are at the top of the page. Deleting a project is in the ⋮ menu, with a list of what goes and what stays."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Hints that go away"}]},{"type":"paragraph","content":[{"type":"text","text":"Short how-to notes on some screens, such as how to select words into an excerpt, show a Got it button. Select it and that note stays hidden in this browser."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-29-sourcework-data-points-and-source-progress',
  p_tool_key => 'transcription',
  p_released_on => '2026-10-29',
  p_title => 'Sourcework: Browse data points, and see each source''s progress',
  p_guide_slugs => array['sourcework-project-overview'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A project's Notebook tab now has three sections: Sources, Data points and Excerpts. Data points lists the findings you have accepted or rejected, so you can browse them without going back to Review, which stays its own tab for deciding. Each source in the list shows a bar for how far it has come: processed, analyzed, reviewed."}]}]}$body$
);
